export const ICC_LIMIT=4*1024*1024;
export const ICC_ORIGINAL_SECTION='round2.source-icc';
export const ICC_ASSIGNED_SECTION='round2.assigned-icc';
export const ICC_IMPORT_ACTION='round2.icc-import-action';
export const ICC_ORIGINAL_TYPE='application/vnd.iccprofile';

// Standard sRGB matrix profile generated by Little CMS.
const nativeSrgb='';
export const srgbIccBytes=()=>Uint8Array.from(atob(nativeSrgb),value=>value.charCodeAt(0));

export function validIccBytes(bytes:Uint8Array){
  if(bytes.length<132||bytes.length>ICC_LIMIT)return false;
  const view=new DataView(bytes.buffer,bytes.byteOffset,bytes.byteLength);
  const length=view.getUint32(0),tags=view.getUint32(128);
  return length>=132&&length<=bytes.length&&view.getUint32(36)===0x61637370&&
    tags<=4096&&132+tags*12<=length;
}
